<?php namespace App\Http\Controllers; use App\Models\{Product,Inventory}; use App\Services\InventoryService; use App\Enums\InventoryMovementType; use Illuminate\Http\Request;
class InventoryController extends Controller {public function __construct(private InventoryService $service){} public function index(){ $branch=auth()->user()->branch_id;$items=Inventory::with('product')->where('branch_id',$branch)->paginate(20);return view('inventory.index',compact('items'));} public function create(){return view('inventory.create');} public function store(Request $r){$p=Product::create(array_merge($r->validate(['name'=>'required','sku'=>'required|unique:products,sku','barcode'=>'nullable|unique:products,barcode','category'=>'nullable','brand'=>'nullable','part_number'=>'nullable','cost_price'=>'required|numeric','selling_price'=>'required|numeric','minimum_stock'=>'required|integer']),['business_id'=>auth()->user()->business_id]));$this->service->adjust($p,auth()->user()->branch_id,(float)$r->input('opening_stock',0),'Opening stock',InventoryMovementType::PURCHASE->value);return redirect()->route('inventory.index')->with('success','Product created.');} public function edit(Product $product){return view('inventory.edit',compact('product'));} public function update(Request $r,Product $product){$product->update($r->validate(['name'=>'required','selling_price'=>'required|numeric','minimum_stock'=>'required|integer','cost_price'=>'required|numeric']));return back()->with('success','Product updated.');} public function destroy(){abort(405);} public function adjust(Request $r,Product $product){$this->service->adjust($product,auth()->user()->branch_id,(float)$r->validate(['quantity'=>'required|numeric'])['quantity'],$r->input('reason','Manual adjustment'));return back()->with('success','Stock adjusted.');}}
